278	function time_ago($date) {
279	    if (empty($date)) return "No date provided";
280	    $periods = ["초", "분", "시간", "일", "주", "개월", "년", "10년"];
281	    $lengths = [60, 60, 24, 7, 4.35, 12, 10];
282	    $now = time();
283	    $unix_date = strtotime($date);
284	    if (!$unix_date) return "Bad date";
285	    
286	    $tense = $now > $unix_date ? "전" : "후";
287	    $difference = abs($now - $unix_date);
288	
289	    for ($j = 0; $difference >= $lengths[$j] && $j < count($lengths) - 1; $j++) {
290	        $difference /= $lengths[$j];
291	    }
292	    $difference = round($difference);
293	
294	    return "$difference{$periods[$j]} $tense";
295	}
